urlset:
{% for element in all_media %}

        {% if element.media_type == 'video' %}
            https://media.themetacity.com{{ url_for('media.show_specific_video', video_id=element.id) }}
        {% elif element.media_type == 'audio' %}
            https://media.themetacity.com{{ url_for('media.show_specific_audio', audio_id=element.id) }}
        {% elif element.media_type == 'code' %}
            https://media.themetacity.com{{ url_for('media.show_specific_code', code_id=element.id) }}
        {% elif element.media_type == 'picture' %}
            https://media.themetacity.com{{ url_for('media.show_specific_picture', picture_id=element.id) }}
        {% endif %}
        {{ element.Parent.date_published.strftime('%Y-%m-%d') }}
        never

{% endfor %}
